SET is_read = 1, read_at = #{now}, update_time = #{now}
WHERE user_id = #{userId} AND id IN
#{id}

UPDATE user_message um

    JOIN message m ON m.id = um.message_id AND m.type = #{type}

SET um.is_read = 1, um.read_at = #{now}, um.update_time = #{now}
WHERE um.user_id = #{userId} AND um.is_read = 0

