mapper.select:
SELECT um.id, um.user_id, um.message_id, um.is_read, um.read_at, um.create_time, um.update_time,
       m.type AS m_type, m.title AS m_title, m.content AS m_content,
       m.link_type AS m_link_type, m.link_target AS m_link_target, m.broadcast AS m_broadcast
FROM user_message um
JOIN message m ON m.id = um.message_id
WHERE um.user_id = #{userId}
AND m.type = #{type}
ORDER BY um.create_time DESC, um.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM user_message um
JOIN message m ON m.id = um.message_id
WHERE um.user_id = #{userId} AND um.is_read = 0 AND m.type = #{type}
